import std/syncio
import std/crypto/rsa

proc hexVal(c: char): int =
  if c in {'0'..'9'}: ord(c) - ord('0')
  elif c in {'a'..'f'}: ord(c) - ord('a') + 10
  else: ord(c) - ord('A') + 10

proc unhex(s: string): seq[byte] =
  result = @[]
  var i = 0
  while i + 1 < s.len:
    result.add byte(hexVal(s[i]) * 16 + hexVal(s[i+1]))
    i += 2

proc bytesOf(s: string): seq[byte] =
  result = @[]
  for c in s: result.add byte(c)

proc check(n, p1, pss: string) =
  var key = default(RsaPublicKey)
  echo initRsaPublicKey(unhex(n), [1'u8, 0, 1], key)
  let msg = bytesOf("hello nimony")
  echo rsaVerifyPkcs1v15(key, rhSha256, msg, unhex(p1))
  echo rsaVerifyPss(key, rhSha384, msg, unhex(pss), 48)
  let other = bytesOf("hello nimonz")
  echo rsaVerifyPkcs1v15(key, rhSha256, other, unhex(p1))
  echo rsaVerifyPss(key, rhSha384, other, unhex(pss), 48)

# modulus, PKCS#1 v1.5/SHA-256 and PSS/SHA-384 signatures from `openssl dgst`
check("", "", "")
check("", "", "")
